/**
 * Password reset links generated by an administrator (Fase 7). Mail is off, so «Olvidé mi contraseña» cannot reach
 * anyone: the admin creates the link and hands it to the person, like an invitation link.
 *
 * The link reuses Better Auth's own reset token (`reset-password:<token>` in `authVerification`), so the existing
 * «Una nueva contraseña» page and `/api/auth/reset-password` do the change: same password rules, single use, and every
 * session of that account is closed. The token is stored only as a hash, under a prefix that no raw token can reach
 * through Better Auth's plain-identifier fallback.
 */
import { createHash } from 'node:crypto';

/** One working day to hand the link over; a new link replaces the old one. */
export const RESET_LINK_HOURS = 24;
/** Better Auth's identifier for password reset tokens. */
export const RESET_IDENTIFIER_PREFIX = 'reset-password:';
/**
 * Stored form of a reset identifier. It must not start with `reset-password:`: Better Auth also looks a token up as a
 * plain identifier, and a stored value under that prefix could then be replayed as a token.
 */
export const RESET_HASH_PREFIX = 'reset-password-hash:';

export function resetIdentifierHash(identifier: string): string {
  return RESET_HASH_PREFIX + createHash('sha256').update(identifier, 'utf8').digest('base64url');
}

/** What `authVerification.identifier` holds for a raw reset token. */
export function storedResetIdentifier(token: string): string {
  return resetIdentifierHash(RESET_IDENTIFIER_PREFIX + token);
}

/** The login page already turns `?reset=1&token=…` into «Una nueva contraseña». */
export function resetLinkUrl(base: string, token: string): string {
  const url = new URL('/login', base);
  url.searchParams.set('reset', '1');
  url.searchParams.set('token', token);
  return url.href;
}

export type ResetLinkTarget = {
  role: string;
  status: string;
  userId: string | null;
};

/**
 * Who can receive a reset link from a workspace admin, beyond the usual «who can you manage» rule. Returns the reason
 * it is refused, or null.
 * - Only active accounts: a pending invitation uses its invitation link, a revoked one must be restored first.
 * - Never an identity that also belongs to another workspace or holds the platform operator grant: the new password
 *   would open those too, and this admin has no say there.
 */
export function resetLinkProblem(
  target: ResetLinkTarget,
  context: { otherMemberships: number; platformOperator: boolean },
): string | null {
  if (!target.userId || target.status === 'invited')
    return 'Esta persona aún no activa su cuenta. Renueva su enlace de invitación.';
  if (target.status !== 'active') return 'Restaura el acceso de esta persona antes de crear el enlace.';
  if (context.platformOperator || context.otherMemberships > 0)
    return 'Esta cuenta también se usa en otro espacio de Daybook. La persona debe recuperar su contraseña desde la página de acceso o con soporte de Daybook.';
  return null;
}
